function firstIndexAtLeast(nums, target) {
  let low = 0;
  let high = nums.length;
  while (low < high) {
    const mid = low + Math.floor((high - low) / 2);
    if (nums[mid] < target) low = mid + 1;
    else high = mid;
  }
  return low;
}

function firstIndexAbove(nums, target) {
  let low = 0;
  let high = nums.length;
  while (low < high) {
    const mid = low + Math.floor((high - low) / 2);
    if (nums[mid] <= target) low = mid + 1;
    else high = mid;
  }
  return low;
}

function firstAndLastIndex(nums, target) {
  const first = firstIndexAtLeast(nums, target);
  if (first === nums.length || nums[first] !== target) return [-1, -1];
  const last = firstIndexAbove(nums, target) - 1;
  return [first, last];
}

