  let low = 0;
  let high = sorted.length;
  while (low < high) {
    const mid = low + Math.floor((high - low) / 2);
    if (sorted[mid] < target) low = mid + 1;
    else high = mid;
  }
  return low;
}

function countBelowEachQuery(nums, queries) {
  const sorted = nums.slice().sort((a, b) => a - b);
  return queries.map((query) => leftmostIndexAtLeast(sorted, query));
}

