def count_below_each_query(nums, queries):
    values = sorted(nums)
    order = sorted(range(len(queries)), key=lambda i: queries[i])
    answers = [0] * len(queries)
    cursor = 0
    for i in order:
        while cursor < len(values) and values[cursor] < queries[i]:
            cursor += 1
        answers[i] = cursor
    return answers

